public class HeaderParser {

    /**
     * Skips bytes until the end of the current line.
     * @param headerPart The headers, which are being parsed.
     * @param end Index of the last byte, which has yet been processed.
     * @return Index of the \r\n sequence, which indicates end of line.
     */
    private int parseEndOfLine(String headerPart, int end) {
        int i = end;
        while (i < headerPart.length() && headerPart.charAt(i) != '\r') {
            i++;
        }
        if (i < headerPart.length() && headerPart.charAt(i) == '\r') {
            i++;
            if (i < headerPart.length() && headerPart.charAt(i) == '\n') {
                return i;
            }
        }
        return -1; // Return -1 if no \r\n sequence is found
    }

    public static void main(String[] args) {
        HeaderParser parser = new HeaderParser();
        String headers = "This is a test header\r\nwith multiple lines\r\nand a newline at the end";
        int end = headers.length() - 1;
        int result = parser.parseEndOfLine(headers, end);
        System.out.println("End of line index: " + result);
    }
}

