public class GraphUtils {

    /**
     * Computes an identity automorphism (i.e. a self-mapping of a graph in which each vertex also maps to itself).
     * @param graph the input graph
     * @param <V> the graph vertex type
     * @param <E> the graph edge type
     * @return a mapping from graph to graph
     */
    public static <V, E> GraphMapping<V, E> identity(Graph<V, E> graph) {
        SimpleGraph<V, E> identityGraph = new SimpleGraph<>(graph.getEdgeFactory());
        identityGraph.addVertexSet(graph.vertexSet());
        identityGraph.addEdgeSet(graph.edgeSet());
        return new GraphMapping<>(graph, identityGraph);
    }
}

