    private int tail;
    private int size;

    public Logger(int capacity) {
        buffer = new LoggingEvent[capacity];
        head = 0;
        tail = 0;
        size = 0;
    }

    public void put(LoggingEvent o) {
        if (size == buffer.length) {
            // Buffer is full, silently drop the event
            return;
        }
        buffer[tail] = o;
        tail = (tail + 1) % buffer.length;
        size++;
    }
}

