public class ByteVector {
    private byte[] data;
    private int size;

    public ByteVector() {
        this.data = new byte[16];
        this.size = 0;
    }

    public ByteVector(final byte[] byteArrayValue, final int byteOffset, final int byteLength) {
        this();
        if (byteArrayValue != null) {
            putByteArray(byteArrayValue, byteOffset, byteLength);
        }
    }

    public ByteVector putByteArray(final byte[] byteArrayValue, final int byteOffset, final int byteLength) {
        if (byteArrayValue == null) {
            for (int i = 0; i < byteLength; i++) {
                data[size++] = 0;
            }
        } else {
            if (size + byteLength > data.length) {
                ensureCapacity(size + byteLength);
            }
            System.arraycopy(byteArrayValue, byteOffset, data, size, byteLength);
            size += byteLength;
        }
        return this;
    }

    private void ensureCapacity(final int minCapacity) {
        final int oldCapacity = data.length;
        if (minCapacity > oldCapacity) {
            final int newCapacity = (oldCapacity * 3) / 2 + 1;
            if (newCapacity < minCapacity) {
                newCapacity = minCapacity;
            }
            data = Arrays.copyOf(data, newCapacity);
        }
    }

    // Other methods and fields can be added here
}

