import java.util.Iterator;

public class YourClassName implements Iterator<YourType> {
    private boolean[] visited;
    private int currentIndex;

    public YourClassName(YourType[] elements) {
        this.visited = new boolean[elements.length];
        this.currentIndex = 0;
    }

    @Override
    public boolean hasNext() {
        while (currentIndex < visited.length && visited[currentIndex]) {
            currentIndex++;
        }
        return currentIndex < visited.length;
    }

    @Override
    public YourType next() {
        if (!hasNext()) {
            throw new NoSuchElementException();
        }
        visited[currentIndex] = true;
        return elements[currentIndex++];
    }
}

public class AbstractTypeStack {
    private Stack<AbstractType> stack;

    public AbstractTypeStack() {
        stack = new Stack<>();
    }

    public void push(AbstractType type) {
        stack.push(type);
    }

    public AbstractType pop(final int elements) {
        if (elements < 0) {
            throw new IllegalArgumentException("Number of elements to pop cannot be negative");
        }
        if (stack.size() < elements) {
            throw new IllegalStateException("Not enough elements in the stack to pop");
        }
        AbstractType[] poppedElements = new AbstractType[elements];
        for (int i = 0; i < elements; i++) {
            poppedElements[i] = stack.pop();
        }
        return poppedElements[0]; // Return the first popped element
    }
}

