public class ListNodeImpl<E> {
    private E value;
    private ListNodeImpl<E> next;

    public ListNodeImpl(E value) {
        this.value = value;
        this.next = null;
    }

    public E getValue() {
        return value;
    }

    public void setValue(E value) {
        this.value = value;
    }

    public ListNodeImpl<E> getNext() {
        return next;
    }

    public void setNext(ListNodeImpl<E> next) {
        this.next = next;
    }

    public boolean unlink(ListNodeImpl<E> node) {
        if (node == null) {
            return false;
        }

        ListNodeImpl<E> current = this;
        ListNodeImpl<E> previous = null;

        while (current != null) {
            if (current == node) {
                if (previous == null) {
                    this.value = current.getNext().getValue();
                    this.next = current.getNext().getNext();
                } else {
                    previous.next = current.getNext();
                }
                return true;
            }
            previous = current;
            current = current.getNext();
        }

        return false;
    }
}

