    int lastSeparatorIndex = filename.lastIndexOf('/');
    if (lastSeparatorIndex == -1) {
        lastSeparatorIndex = filename.lastIndexOf('\\');
    }
    if (lastSeparatorIndex == -1) {
        return -1;
    }
    int dotIndex = filename.lastIndexOf('.', lastSeparatorIndex);
    if (dotIndex == -1 || dotIndex > lastSeparatorIndex) {
        return -1;
    }
    return dotIndex;
}

public boolean isExpired(long timestamp, long expiredThreshold) {
    return timestamp - expiredThreshold > System.currentTimeMillis();
}

