    public void append(LoggingEvent event) {
        for (Socket client : connectedClients) {
            try {
                client.getOutputStream().write(event.getMessage().getBytes());
                client.getOutputStream().flush();
            } catch (IOException e) {
                e.printStackTrace();
            }
        }
    }

