import java.io.IOException;

public int readTag() throws IOException {
    int tag = 0;
    int shift = 0;
    while (true) {
        int b = readByte();
        if (b == -1) {
            return 0;
        }
        tag |= (b & 0x7F) << shift;
        shift += 7;
        if ((b & 0x80) == 0) {
            return tag;
        }
    }
}

import java.util.Arrays;

public class ByteVector {
    private byte[] data;

    public ByteVector() {
        this.data = new byte[0];
    }

    public ByteVector put11(final int byteValue1, final int byteValue2) {
        byte[] newData = Arrays.copyOf(this.data, this.data.length + 2);
        newData[this.data.length] = (byte) (byteValue1 & 0xFF);
        newData[this.data.length + 1] = (byte) (byteValue2 & 0xFF);
        this.data = newData;
        return this;
    }

    public static void main(String[] args) {
        ByteVector vector = new ByteVector();
        vector.put11(10, 20);
        System.out.println(Arrays.toString(vector.data)); // Output: [10, 20]
    }
}

